/* ===== Round 2: Videos / Reels feed ===== */
UI.rl={tab:'foryou',idx:0,muted:true,paused:false,play:{}};
const RPILLS=[['foryou','For You'],['following','Following'],['nearby','Nearby (my area)'],['offers','Offers'],['products','Products'],['services','Services'],['c:electronics','Electronics'],['c:clothing','Fashion'],['c:food','Food'],['c:wedding','Wedding'],['c:mobile','Mobile'],['c:mechanic','Repair']];
const fmtN=n=>n>=1000?(Math.round(n/100)/10)+'K':String(n);
const isSvcId=x=>/-sv\d+$/.test(x);
function reelList(){let l=allVideos().filter(v=>v.m.reels!==false&&v.m.status==='approved');const tb=UI.rl.tab;
 if(tb==='following')l=l.filter(v=>S.follows.includes(v.o.id));else if(tb==='nearby')l=l.filter(v=>dist(v.o)<=2.5);else if(tb==='offers')l=l.filter(v=>(v.m.tags||[]).some(x=>isSvcId(x)?(svOffer((svcObj(x)||{}).svc||{id:x})):(prod(x)&&hasOffer(prod(x)))));else if(tb==='products')l=l.filter(v=>(v.m.tags||[]).some(x=>!isSvcId(x)&&prod(x)));else if(tb==='services')l=l.filter(v=>(v.m.tags||[]).some(isSvcId));else if(tb.startsWith('c:'))l=l.filter(v=>v.o.cat===tb.slice(2));
 if(!UI.rl.rank){UI.rl.rank={};[...allVideos()].sort((a,b)=>(b.m.likes+b.m.views/10)-(a.m.likes+a.m.views/10)).forEach((v,i)=>UI.rl.rank[v.m.id]=i)}return [...l].sort((a,b)=>(UI.rl.rank[a.m.id]??999)-(UI.rl.rank[b.m.id]??999))}
const reelSkel=()=>`<div class="reels" aria-busy="true" aria-label="${t('Loading')}"><div class="rtop"><div class="skel" style="height:40px;width:70%"></div></div><div class="rbody"><div class="rfeed"><div class="rv"><div class="skel" style="position:absolute;inset:0;border-radius:0"></div></div></div></div></div>`;
const dataSaver=()=>S.demo.lite||(navigator.connection&&navigator.connection.saveData);
function linkMini(it,vid){return it.k==='p'?`<div class="rlk"><div class="art" style="--h:${it.p.hue}">${it.p.emoji}</div><div style="min-width:0"><b class="small truncate" style="display:block">${esc(it.name)}</b><div class="small">${it.price}</div></div>${(it.p.avail&&it.p.stock>0)?`<button class="btn p" data-act="vlAdd" data-id="${it.id}">${ic('cart',14)} ${t('Add to cart')}</button>`:`<a class="btn g" href="#prod-${it.id}">${t('View')}</a>`}</div>`:`<div class="rlk"><div class="art" style="--h:${it.owner.hue}">${it.owner.emoji}</div><div style="min-width:0"><b class="small truncate" style="display:block">${esc(it.name)}</b><div class="small">${esc(it.price)}</div></div><div style="grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:6px"><button class="btn p" data-act="vlEnq" data-id="${it.id}">${t('Enquire')}</button><a class="btn g" href="#service-${it.id}">${t('View')}</a></div></div>`}
function reelSection(v,i){const m=v.m,o=v.o,liked=S.likes.includes(m.id),links=(m.tags||[]).map(tagItem).filter(Boolean),op=openState(o),saver=dataSaver()&&!UI.rl.play[m.id],fail=S.demo.videoFail;
 return `<section class="rv ${UI.rl.paused?'paused':''}" data-i="${i}" data-id="${m.id}" style="--d:${m.dur}s" aria-label="${esc(m.title)}"><div class="rposter" data-act="rtap" role="button" tabindex="0" aria-label="${t('Play or pause')}">${art(m.thumb,m.t==='yt'?0:330,'')}</div><div class="rpp"><span>${ic('play',30)}</span></div><div class="rshade"></div>
 ${saver?`<div class="rsave"><button class="btn" style="background:#fff;color:#000" data-act="rplay" data-id="${m.id}">${ic('play',18)} ${t('Tap to play')}</button><div class="xs" style="position:absolute;bottom:90px;opacity:.85">${t('Data saver is on')}</div></div>`:''}
 ${fail?`<div class="rstate"><div style="font-size:2.4rem">⚠️</div><b>${t('This video failed to load')}</b><button class="btn" style="background:#fff;color:#000" data-act="rretry">${ic('refresh',16)} ${t('Retry')}</button><a class="small" style="color:#fff;text-decoration:underline" target="_blank" rel="noopener" href="${esc(extUrl(m))}">${t('Open in')} ${mLabel(m)}</a></div>`:''}
 ${!online?`<div class="rstate"><div style="font-size:2.4rem">📡</div><b>${t('You are offline')}</b><button class="btn" style="background:#fff;color:#000" data-act="retry">${t('Tap to retry')}</button></div>`:''}
 <div class="rrail"><div style="text-align:center"><button data-act="vlike" data-id="${m.id}" class="${liked?'on':''}" aria-pressed="${liked}" aria-label="${t('Like')}"><svg class="ic ${liked?'fill':''}" width="26" height="26" viewBox="0 0 24 24"><path d="${IC.heart}"/></svg></button><div class="n" id="lk_${m.id}">${fmtN(m.likes+(liked&&!m.likedBase?1:0))}</div></div><div style="text-align:center"><button data-act="vcomm" data-id="${m.id}" aria-label="${t('Comments')}">${ic('chat',24)}</button><div class="n">${(m.comments||[]).length}</div></div><div style="text-align:center"><button data-act="vshare" data-id="${m.id}" aria-label="${t('Share')}">${ic('share',24)}</button><div class="n">${fmtN(m.shares)}</div></div>${links.length?`<div style="text-align:center"><button data-act="vshop" data-id="${m.id}" aria-label="${t('Shop this video')}">${ic('cart',24)}</button><div class="n">${links.length}</div></div>`:''}<button data-act="vmore" data-id="${m.id}" aria-label="${t('More options')}">${ic('dots',24)}</button></div>
 <div class="rinfo"><div class="row" style="gap:8px"><a href="#${o.id[0]==='s'?'svc':'biz'}-${o.id}" class="row" style="gap:8px;min-width:0"><span class="art" style="--h:${o.hue};width:40px;height:40px;border-radius:50%;font-size:1.2rem;aspect-ratio:auto;filter:none">${o.emoji}</span><b class="truncate">${esc(nm(o.name))}</b>${o.verified?`<span style="color:#5eead4" title="${t('Verified')}">${ic('shield',16)}</span>`:''}</a>${followBtn(o.id)}</div><div class="small" style="overflow-wrap:anywhere">${esc(m.cap)}</div><div class="small" style="color:#fdba74">${(m.hashtags||[]).map(h=>esc(h)).join(' ')}</div><div class="row xs" style="gap:8px;flex-wrap:wrap"><span>${ic('pin',12)} ${dist(o).toFixed(1)} km</span><span class="badge ${op.open?'ok':'bad'}" style="background:rgba(0,0,0,.4)">${op.open?'● '+t('Open now'):'○ '+esc(op.label)}</span></div>${links.length?`<div class="rlinks" aria-label="${t('Linked products and services')}">${links.slice(0,4).map(l=>linkMini(l,m.id)).join('')}</div>`:''}</div><div class="rprog"><i></i></div></section>`}
function reelSideHtml(v){if(!v)return '';const m=v.m,links=(m.tags||[]).map(tagItem).filter(Boolean);return `<h3>${esc(m.title)}</h3><div class="small t2" style="margin:4px 0 10px">${fmtN(m.views)} ${t('views')} · ${fmtN(m.likes)} ${t('likes')}</div><h4>${t('Linked products & services')}</h4><div class="stack" style="margin:8px 0 14px">${links.map(l=>`<div class="card pad row" style="gap:8px"><div class="art mini" style="--h:${l.k==='p'?l.p.hue:l.owner.hue};width:44px;height:44px;filter:none">${l.k==='p'?l.p.emoji:l.owner.emoji}</div><div class="grow" style="min-width:0"><b class="small truncate" style="display:block">${esc(l.name)}</b><div class="xs t2">${esc(l.price)}</div></div>${l.k==='p'?`<button class="btn p sm" data-act="vlAdd" data-id="${l.id}">${t('Add')}</button>`:`<button class="btn p sm" data-act="vlEnq" data-id="${l.id}">${t('Enquire')}</button>`}</div>`).join('')||`<span class="small t2">${t('Nothing linked.')}</span>`}</div><h4>${t('Comments')}</h4><div class="stack" style="margin:8px 0">${(m.comments||[]).map(c=>`<div class="small"><b>${esc(c.name)}</b> <span class="t2">${esc(c.text)}</span>${c.st==='pending'?` <span class="badge warn">${t('Awaiting moderation')}</span>`:''}</div>`).join('')||`<span class="small t2">${t('No comments yet.')}</span>`}</div><button class="btn g sm" data-act="vcomm" data-id="${m.id}">${t('Add a comment')}</button>`}
V.videos=arg=>{const all=allVideos(),target=arg?all.find(v=>v.m.id===arg):null;
 if(arg&&(!target||target.m.status==='removed'||target.m.status==='rejected'))return `<div class="reels"><div class="rtop"><button class="iconbtn" data-act="rback" aria-label="${t('Back')}">${ic('cl',22)}</button></div><div class="rbody"><div class="rstate" style="position:static;background:none;width:100%"><div style="font-size:2.6rem">🚫</div><h3>${t('This video is unavailable')}</h3><p class="t2" style="color:#cfc4b6">${t('It was removed by the owner or by ApnaTown.')}</p><a class="btn" style="background:#fff;color:#000" href="#videos">${t('Watch other videos')}</a></div></div></div>`;
 if(target&&!reelList().some(v=>v.m.id===arg))UI.rl.tab='foryou';const l=reelList();let idx=target?Math.max(0,l.findIndex(v=>v.m.id===arg)):Math.min(UI.rl.idx,Math.max(0,l.length-1));UI.rl.idx=idx;
 post.push(()=>reelSetup(l));
 let body;if(!l.length)body=`<div class="rstate" style="position:static;background:none;width:100%;height:100%"><div style="font-size:2.6rem">${UI.rl.tab==='following'?'🔔':'📍'}</div><h3>${UI.rl.tab==='following'?t('Follow shops to see their videos here'):UI.rl.tab==='nearby'?t('No videos nearby yet'):t('No videos here yet')}</h3><p style="color:#cfc4b6;max-width:30ch">${UI.rl.tab==='following'?t('Tap Follow on any video to build your feed.'):t('Try another area or pick another tab.')}</p><button class="btn" style="background:#fff;color:#000" data-act="rtab" data-v="foryou">${t('Go to For You')}</button></div>`;else body=l.map((v,i)=>reelSection(v,i)).join('');
 return `<div class="reels" id="reels" role="region" aria-label="${t('Videos and reels')}"><div class="rtop"><button class="iconbtn" data-act="rback" aria-label="${t('Back')}">${ic('cl',22)}</button><div class="rpills" role="tablist" aria-label="${t('Video categories')}">${RPILLS.map(([k,l])=>`<button role="tab" aria-selected="${UI.rl.tab===k}" class="rpill ${UI.rl.tab===k?'on':''}" data-act="rtab" data-v="${k}">${t(l)}</button>`).join('')}</div><button class="iconbtn" data-act="rmute" aria-pressed="${UI.rl.muted}" aria-label="${UI.rl.muted?t('Unmute'):t('Mute')}">${UI.rl.muted?'🔇':'🔊'}</button></div><div class="rbody"><div class="rfeed" id="rfeed" tabindex="0" aria-label="${t('Video feed. Use up and down arrows.')}">${body}</div><aside class="rside" id="rside" aria-label="${t('Comments and linked products')}">${reelSideHtml(l[idx])}</aside></div></div>`};
function reelSetup(l){const f=$('#rfeed');if(!f||!l.length)return;const secs=$$('.rv',f);const go_=i=>{const e=secs[i];if(e)e.scrollIntoView({block:'start',behavior:'auto'})};go_(UI.rl.idx);requestAnimationFrame(()=>{go_(UI.rl.idx);requestAnimationFrame(()=>go_(UI.rl.idx))});let cur_=-1,ready=false;setTimeout(()=>{go_(UI.rl.idx)},120);setTimeout(()=>{ready=true},600);
 const act=i=>{if(i===cur_)return;cur_=i;UI.rl.idx=i;secs.forEach((s,k)=>s.classList.toggle('on',k===i));const v=l[i];if(!v)return;if(!v.m._seen){v.m._seen=1;v.m.views++;save()}const sd=$('#rside');if(sd)sd.innerHTML=reelSideHtml(v);try{history.replaceState(history.state,'','#videos-'+v.m.id)}catch(e){}};
 if('IntersectionObserver' in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(ready&&e.isIntersecting&&e.intersectionRatio>=.6)act(+e.target.dataset.i)}),{root:f,threshold:[.6]});secs.forEach(s=>io.observe(s))}act(UI.rl.idx);
 secs.forEach((s,i)=>s.querySelector('.rprog i').addEventListener('animationend',()=>{if(i===cur_&&i<secs.length-1&&!UI.rl.paused)f.scrollTo({top:(i+1)*f.clientHeight,behavior:'smooth'})}));f.focus({preventScroll:true})}
document.addEventListener('keydown',e=>{const f=$('#rfeed');if(!f||!$('#reels'))return;if(e.target.closest&&e.target.closest('input,textarea,select'))return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();f.scrollBy({top:(e.key==='ArrowDown'?1:-1)*f.clientHeight,behavior:'smooth'})}else if(e.key===' '&&e.target===f){e.preventDefault();A.rtap()}else if(e.key==='Escape'&&!$('#sheetRoot')){A.rback()}},true);
A.rback=()=>{if(history.length>1)history.back();else go('home')};
A.rtab=el=>{UI.rl.tab=el.dataset.v;UI.rl.idx=0;try{history.replaceState(history.state,'','#videos')}catch(e){}render()};
A.rmute=()=>{UI.rl.muted=!UI.rl.muted;save();render(true);toast(UI.rl.muted?t('Muted'):t('Unmuted'),'info')};
A.rtap=()=>{UI.rl.paused=!UI.rl.paused;$$('.rv').forEach(s=>s.classList.toggle('paused',UI.rl.paused))};
A.rplay=el=>{UI.rl.play[el.dataset.id]=true;const s=el.closest('.rsave');s&&s.remove()};
A.rretry=()=>{S.demo.videoFail=false;save();toast(t('Loading again…'),'refresh');render(true)};
A.vlike=el=>{if(needLogin('Log in to like videos. You will come back to this video.'))return;const id=el.dataset.id,m=allVideos().find(v=>v.m.id===id).m,was=S.likes.includes(id);S.likes=was?S.likes.filter(x=>x!==id):[...S.likes,id];m.likes+=was?-1:1;save();el.classList.toggle('on',!was);el.setAttribute('aria-pressed',!was);el.querySelector('svg').classList.toggle('fill',!was);const n=$('#lk_'+id);if(n)n.textContent=fmtN(m.likes);if(!was&&!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate([{transform:'scale(1)'},{transform:'scale(1.35)'},{transform:'scale(1)'}],{duration:300})};
A.vshare=el=>{const id=el.dataset.id,v=allVideos().find(x=>x.m.id===id),u=shareUrl('videos-'+id);v.m.shares++;save();sheet(`<h3>${t('Share')}</h3><p class="small muted">${esc(v.m.title)}</p><div class="stack" style="margin-top:10px"><a class="btn s block" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(v.m.title+' '+u)}">${ic('chat',18)} WhatsApp</a><button class="btn g block" data-act="copy" data-v="${esc(u)}">${ic('copy',18)} ${t('Copy link')}</button><button class="btn g block" data-act="vnative" data-v="${esc(u)}" data-t="${esc(v.m.title)}">${ic('share',18)} ${t('More')}</button></div>`,{label:'Share'})};
A.vnative=el=>{if(navigator.share)navigator.share({title:el.dataset.t,url:el.dataset.v}).catch(()=>{});else A.copy({dataset:{v:el.dataset.v}})};
A.vshop=el=>{const v=allVideos().find(x=>x.m.id===el.dataset.id),links=(v.m.tags||[]).map(tagItem).filter(Boolean);sheet(`<div class="row between"><h3>${t('Shop this video')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="stack" style="margin-top:10px">${links.map(l=>`<div class="card pad row" style="gap:10px">${l.k==='p'?art(l.p.emoji,l.p.hue,'mini'):art(l.owner.emoji,l.owner.hue,'mini')}<div class="grow" style="min-width:0"><b class="small" style="display:block">${esc(l.name)}</b><div class="small t2">${esc(l.price)}</div></div>${l.k==='p'?`<a class="btn g sm" href="#prod-${l.id}" data-act="closeSheet">${t('View')}</a><button class="btn p sm" data-act="vlAdd" data-id="${l.id}">${t('Add')}</button>`:`<a class="btn g sm" href="#service-${l.id}" data-act="closeSheet">${t('View')}</a><button class="btn p sm" data-act="vlEnq" data-id="${l.id}">${t('Enquire')}</button>`}</div>`).join('')}</div>`,{label:'Shop this video'})};
A.vlAdd=el=>{if(addToCart(el.dataset.id,1))toast(t('Added to cart'),'cart')};
A.vlEnq=el=>{const i=tagItem(el.dataset.id);if(!i)return;closeSheet();enqSheet(i.owner.id,i.name)};
A.vmore=el=>{const v=allVideos().find(x=>x.m.id===el.dataset.id);sheet(`<h3>${t('More options')}</h3><div class="stack" style="margin-top:10px"><button class="btn g block" data-act="reportMedia" data-title="${esc(v.m.title)}">${ic('flag',18)} ${t('Report video')}</button><a class="btn g block" target="_blank" rel="noopener" href="${esc(extUrl(v.m))}">${t('Open in')} ${mLabel(v.m)}</a><button class="btn g block" data-act="copy" data-v="${esc(shareUrl('videos-'+v.m.id))}">${ic('copy',18)} ${t('Copy link')}</button></div>`,{label:'More options'})};
A.vcomm=el=>{if(needLogin('Log in to comment. You will come back to this video.'))return;const v=allVideos().find(x=>x.m.id===el.dataset.id);sheet(`<div class="row between"><h3>${t('Comments')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="stack" style="margin:10px 0">${(v.m.comments||[]).map(c=>`<div class="small"><b>${esc(c.name)}</b> ${esc(c.text)}${c.st==='pending'?` <span class="badge warn">${t('Awaiting moderation')}</span>`:''}</div>`).join('')||`<span class="muted small">${t('No comments yet.')}</span>`}</div><form data-form="vcomment" class="stack"><input type="hidden" name="id" value="${v.m.id}">${field('Add a comment','text','',{req:1})}<div class="xs muted">${t('Comments are checked by our team before everyone sees them.')}</div><button class="btn p">${t('Post')}</button></form>`,{label:'Comments'})};
F.vcomment=d=>{const v=allVideos().find(x=>x.m.id===d.id);v.m.comments=v.m.comments||[];v.m.comments.push({name:S.user.name,text:d.text,ts:Date.now(),st:'pending'});save();closeSheet();toast(t('Comment sent. It appears after moderation.'),'chat');const sd=$('#rside');if(sd)sd.innerHTML=reelSideHtml(v)};
